var telemetry = global.get('hidroTelemetryCurrent');
if (!telemetry || !telemetry.values) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'sin telemetria' });
    return null;
}

var values = telemetry.values;
var qualityTags = [
    ['ph_agua_cruda', 'pH'],
    ['turbidez_agua_cruda', 'NTU'],
    ['conductividad_agua_cruda', 'uS/cm'],
    ['ph_agua_tratada', 'pH'],
    ['turbidez_agua_tratada', 'NTU'],
    ['conductividad_agua_tratada', 'uS/cm']
];

var telemetryTags = [
    ['caudal_bomba_principal', 'numeric'],
    ['caudal_distribucion', 'numeric'],
    ['presion_bomba_principal', 'numeric'],
    ['nivel_tanque_agua_cruda', 'bool'],
    ['bomba_principal_estado', 'bool'],
    ['dosificador_sulfato_estado', 'bool'],
    ['dosificador_cloro_estado', 'bool'],
    ['modo_remoto_habilitado', 'bool'],
    ['plc_en_falla', 'bool']
];

var messages = [];

qualityTags.forEach(function (item) {
    var tag = item[0];
    var unit = item[1];
    var value = Number(values[tag]);
    if (Number.isFinite(value)) {
        messages.push({
            query: 'INSERT INTO quality_history (tag_id, value_numeric, unit, quality, source, recorded_at) VALUES ($1, $2, $3, $4, $5, now());',
            params: [tag, value, unit, 'good', 'node-red']
        });
    }
});

telemetryTags.forEach(function (item) {
    var tag = item[0];
    var kind = item[1];
    if (values[tag] === undefined || values[tag] === null) return;

    if (kind === 'bool') {
        messages.push({
            query: 'INSERT INTO telemetry_history (tag_id, value_bool, quality, source, recorded_at) VALUES ($1, $2, $3, $4, now());',
            params: [tag, Boolean(values[tag]), 'good', 'node-red']
        });
    } else {
        var numeric = Number(values[tag]);
        if (Number.isFinite(numeric)) {
            messages.push({
                query: 'INSERT INTO telemetry_history (tag_id, value_numeric, quality, source, recorded_at) VALUES ($1, $2, $3, $4, now());',
                params: [tag, numeric, 'good', 'node-red']
            });
        }
    }
});

node.status({ fill: 'green', shape: 'dot', text: messages.length + ' inserts' });
return [messages];

var tag = msg.req.query.tag || 'ph_agua_tratada';
var limit = parseInt(msg.req.query.limit || '200', 10);
if (!Number.isFinite(limit) || limit < 1 || limit > 2000) limit = 200;
msg.query = 'SELECT tag_id, value_numeric, unit, quality, recorded_at FROM quality_history WHERE tag_id = $1 ORDER BY recorded_at DESC LIMIT $2;';
msg.params = [tag, limit];
return msg;
